use std::fs::{self, Metadata};
use std::os::unix::ffi::OsStrExt;
use std::os::unix::fs::{FileTypeExt, MetadataExt, PermissionsExt};
use std::path::Path;
use std::time::{Duration, SystemTime, UNIX_EPOCH};

// ---------- size ----------
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SizeKind { Exact, Min, Max }
#[derive(Debug, Clone, Copy)]
pub struct SizeConstraint { pub kind: SizeKind, pub value: u64 }

pub fn parse_size(s: &str) -> Result<SizeConstraint, String> {
    let err = || format!("'{}' is not a valid size constraint. See 'fd --help'.", s);
    let (kind, rest) = if let Some(r) = s.strip_prefix('+') {
        (SizeKind::Min, r)
    } else if let Some(r) = s.strip_prefix('-') {
        (SizeKind::Max, r)
    } else {
        (SizeKind::Exact, s)
    };
    // split digits and unit
    let digit_end = rest.find(|c: char| !c.is_ascii_digit()).unwrap_or(rest.len());
    if digit_end == 0 { return Err(err()); }
    let (num_s, unit_s) = rest.split_at(digit_end);
    if unit_s.is_empty() { return Err(err()); }
    let num: u64 = num_s.parse().map_err(|_| err())?;
    let unit_lower = unit_s.to_ascii_lowercase();
    let (power, binary): (u32, bool) = match unit_lower.as_str() {
        "b" => (0, false),
        "k" | "kb" => (1, false),
        "ki" | "kib" => (1, true),
        "m" | "mb" => (2, false),
        "mi" | "mib" => (2, true),
        "g" | "gb" => (3, false),
        "gi" | "gib" => (3, true),
        "t" | "tb" => (4, false),
        "ti" | "tib" => (4, true),
        _ => return Err(err()),
    };
    let base: u64 = if binary { 1024 } else { 1000 };
    let mut value = num;
    for _ in 0..power {
        value = value.saturating_mul(base);
    }
    Ok(SizeConstraint { kind, value })
}

impl SizeConstraint {
    pub fn matches(&self, size: u64) -> bool {
        match self.kind {
            SizeKind::Exact => size == self.value,
            SizeKind::Min => size >= self.value,
            SizeKind::Max => size <= self.value,
        }
    }
}

// ---------- owner ----------
#[derive(Debug, Clone, Copy)]
pub struct OwnerSide { pub negate: bool, pub id: u32 }
#[derive(Debug, Clone, Copy, Default)]
pub struct OwnerFilter { pub user: Option<OwnerSide>, pub group: Option<OwnerSide> }

fn lookup_user(name: &str) -> Option<u32> {
    let c = std::ffi::CString::new(name).ok()?;
    unsafe {
        let pw = libc::getpwnam(c.as_ptr());
        if pw.is_null() { None } else { Some((*pw).pw_uid) }
    }
}
fn lookup_group(name: &str) -> Option<u32> {
    let c = std::ffi::CString::new(name).ok()?;
    unsafe {
        let gr = libc::getgrnam(c.as_ptr());
        if gr.is_null() { None } else { Some((*gr).gr_gid) }
    }
}

fn parse_owner_side(s: &str, is_group: bool, whole: &str) -> Result<Option<OwnerSide>, String> {
    if s.is_empty() { return Ok(None); }
    let (negate, rest) = if let Some(r) = s.strip_prefix('!') { (true, r) } else { (false, s) };
    if let Ok(id) = rest.parse::<u32>() {
        return Ok(Some(OwnerSide { negate, id }));
    }
    let id_opt = if is_group { lookup_group(rest) } else { lookup_user(rest) };
    match id_opt {
        Some(id) => Ok(Some(OwnerSide { negate, id })),
        None => {
            if is_group {
                Err(format!("'{}' is not a recognized group name", rest))
            } else {
                Err(format!("'{}' is not a recognized user name", rest))
            }
        }
    }
    // whole unused except in caller for colon error
    #[allow(unreachable_code)] { let _ = whole; }
}

pub fn parse_owner(s: &str) -> Result<OwnerFilter, String> {
    if s.matches(':').count() > 1 {
        return Err(format!("more than one ':' present in owner string '{}'. See 'fd --help'.", s));
    }
    let (user_s, group_s) = match s.split_once(':') {
        Some((u, g)) => (u, Some(g)),
        None => (s, None),
    };
    let user = parse_owner_side(user_s, false, s)?;
    let group = match group_s {
        Some(g) => parse_owner_side(g, true, s)?,
        None => None,
    };
    Ok(OwnerFilter { user, group })
}

impl OwnerFilter {
    pub fn matches(&self, md: &Metadata) -> bool {
        if let Some(u) = self.user {
            let eq = md.uid() == u.id;
            if eq == u.negate { return false; }
        }
        if let Some(g) = self.group {
            let eq = md.gid() == g.id;
            if eq == g.negate { return false; }
        }
        true
    }
    pub fn is_empty(&self) -> bool { self.user.is_none() && self.group.is_none() }
}

// ---------- types ----------
#[derive(Debug, Clone, Default)]
pub struct TypeFilter {
    pub file: bool,
    pub directory: bool,
    pub symlink: bool,
    pub block_device: bool,
    pub char_device: bool,
    pub socket: bool,
    pub pipe: bool,
    pub executable: bool,
    pub empty: bool,
}

impl TypeFilter {
    pub fn from_values(vals: &[String]) -> Self {
        let mut f = TypeFilter::default();
        for v in vals {
            match v.as_str() {
                "file" => f.file = true,
                "directory" => f.directory = true,
                "symlink" => f.symlink = true,
                "block-device" => f.block_device = true,
                "char-device" => f.char_device = true,
                "socket" => f.socket = true,
                "pipe" => f.pipe = true,
                "executable" => { f.executable = true; f.file = true; },
                "empty" => f.empty = true,
                _ => {}
            }
        }
        if f.empty && !f.file && !f.directory {
            // empty alone (or with other non-file/dir types) implies file+dir,
            // but only if the user did not specify executable-implied file?
            // The rule applied in fd: if empty is set and neither file nor directory
            // were *explicitly* selected, add both. However executable sets file
            // internally, which prevents adding directory. We track that above:
            // executable already set file=true, so this branch reflects fd behaviour
            // for cases like `-t l -t e` (file/dir both false) vs `-t x -t e`.
            f.file = true;
            f.directory = true;
        }
        f
    }
    pub fn matches(&self, path: &Path, ft: &fs::FileType) -> bool {
        // executable / empty are additional constraints
        if self.executable && !is_executable(path) {
            return false;
        }
        if self.empty && !is_empty(path, ft) {
            return false;
        }
        // primary types
        let mut any_primary = false;
        let mut pass = false;
        if self.file { any_primary = true; if ft.is_file() { pass = true; } }
        if self.directory { any_primary = true; if ft.is_dir() { pass = true; } }
        if self.symlink { any_primary = true; if ft.is_symlink() { pass = true; } }
        if self.block_device { any_primary = true; if ft.is_block_device() { pass = true; } }
        if self.char_device { any_primary = true; if ft.is_char_device() { pass = true; } }
        if self.socket { any_primary = true; if ft.is_socket() { pass = true; } }
        if self.pipe { any_primary = true; if ft.is_fifo() { pass = true; } }
        // If only executable/empty were given, `file` was implied for executable,
        // and file+dir for empty, so any_primary reflects that.
        if !any_primary {
            return true;
        }
        pass
    }
}

pub fn effective_metadata(path: &Path) -> Option<Metadata> {
    // metadata following symlinks if possible, else symlink metadata
    match fs::metadata(path) {
        Ok(m) => Some(m),
        Err(_) => fs::symlink_metadata(path).ok(),
    }
}

pub fn is_executable(path: &Path) -> bool {
    if let Some(md) = effective_metadata(path) {
        md.permissions().mode() & 0o111 != 0
    } else {
        false
    }
}

pub fn is_empty(path: &Path, ft: &fs::FileType) -> bool {
    if ft.is_file() {
        if let Some(md) = effective_metadata(path) {
            return md.len() == 0;
        }
        false
    } else if ft.is_dir() {
        match fs::read_dir(path) {
            Ok(mut it) => it.next().is_none(),
            Err(_) => false,
        }
    } else {
        false
    }
}

// ---------- extensions ----------
pub fn extension_matches(file_name: &std::ffi::OsStr, extensions: &[String]) -> bool {
    let name = file_name.to_string_lossy().to_lowercase();
    // need a dot that is not the first character, after which the remainder
    // equals one of the extensions (extensions are already normalised/lowered)
    for ext in extensions {
        // check any dot position >0 such that suffix after dot == ext
        // equivalent to name ends with ".{ext}" and the dot is not at 0
        let pat = format!(".{}", ext);
        if name.len() > pat.len() && name.ends_with(&pat) {
            return true;
        }
        if ext.is_empty() && name.len() > 1 && name.ends_with('.') {
            // file like "file." : dot not at start, remainder ""
            return true;
        }
    }
    false
}

pub fn normalize_extension(e: &str) -> String {
    e.trim_start_matches('.').to_lowercase()
}

// ---------- time ----------
pub fn parse_time_filter(s: &str) -> Result<SystemTime, ()> {
    // @timestamp
    if let Some(rest) = s.strip_prefix('@') {
        if let Ok(v) = rest.parse::<u64>() {
            // This intentionally mirrors fd: UNIX_EPOCH + Duration may panic on overflow
            return Ok(UNIX_EPOCH + Duration::from_secs(v));
        }
        return Err(());
    }
    // RFC3339 / zoned / timestamp
    if let Ok(z) = s.parse::<jiff::Zoned>() {
        let ts = z.timestamp();
        return Ok(timestamp_to_system_time(ts));
    }
    if let Ok(ts) = s.parse::<jiff::Timestamp>() {
        return Ok(timestamp_to_system_time(ts));
    }
    if let Ok(dt) = s.parse::<jiff::civil::DateTime>() {
        // Interpret as local time; jiff TimeZone::system falls back to UTC when no tz db
        let zone = jiff::tz::TimeZone::system();
        if let Ok(z) = dt.to_zoned(zone) {
            return Ok(timestamp_to_system_time(z.timestamp()));
        } else {
            // try UTC
            if let Ok(z) = dt.to_zoned(jiff::tz::TimeZone::UTC) {
                return Ok(timestamp_to_system_time(z.timestamp()));
            }
            return Err(());
        }
    }
    if let Ok(d) = s.parse::<jiff::civil::Date>() {
        let dt = d.at(0, 0, 0, 0);
        let zone = jiff::tz::TimeZone::system();
        if let Ok(z) = dt.to_zoned(zone) {
            return Ok(timestamp_to_system_time(z.timestamp()));
        } else if let Ok(z) = dt.to_zoned(jiff::tz::TimeZone::UTC) {
            return Ok(timestamp_to_system_time(z.timestamp()));
        } else {
            return Err(());
        }
    }
    if let Ok(span) = s.parse::<jiff::Span>() {
        // now - span
        let now = jiff::Zoned::now();
        if let Ok(z) = now.checked_sub(span) {
            return Ok(timestamp_to_system_time(z.timestamp()));
        }
        // fallback: try converting span to a duration for time-only spans
        if let Ok(dur) = span.to_duration(jiff::SpanRelativeTo::days_are_24_hours()) {
            let now_st = SystemTime::now();
            return Ok(now_st - dur);
        }
        return Err(());
    }
    Err(())
}

fn timestamp_to_system_time(ts: jiff::Timestamp) -> SystemTime {
    let sec = ts.as_second();
    let nanos = ts.subsec_nanosecond();
    if sec >= 0 {
        UNIX_EPOCH + Duration::new(sec as u64, nanos as u32)
    } else {
        // nanos is signed and already reflects sub-second within the second?
        // jiff: as_second is floor? subsec_nanosecond is >=0 . Compute: epoch - (duration)
        // Represent time = sec seconds + nanos, with sec negative.
        // Use checked arithmetic with i128
        let total_nanos: i128 = sec as i128 * 1_000_000_000 + nanos as i128;
        if total_nanos >= 0 {
            UNIX_EPOCH + Duration::new((total_nanos / 1_000_000_000) as u64, (total_nanos % 1_000_000_000) as u32)
        } else {
            let neg = (-total_nanos) as u128;
            UNIX_EPOCH - Duration::new((neg / 1_000_000_000) as u64, (neg % 1_000_000_000) as u32)
        }
    }
}

pub fn metadata_time_matches(md: &Metadata, within: Option<SystemTime>, before: Option<SystemTime>) -> bool {
    if within.is_none() && before.is_none() { return true; }
    let mtime = match md.modified() {
        Ok(t) => t,
        Err(_) => return false,
    };
    if let Some(w) = within {
        if !(mtime > w) { return false; }
    }
    if let Some(b) = before {
        if !(mtime < b) { return false; }
    }
    true
}

// helper used by other modules: bytes of an OsStr
pub fn os_bytes(s: &std::ffi::OsStr) -> &[u8] {
    s.as_bytes()
}
