use std::collections::HashMap;
use std::fs::Metadata;
use std::os::unix::fs::{MetadataExt, PermissionsExt};

#[derive(Debug, Clone, PartialEq)]
pub enum Color {
    Black, Red, Green, Yellow, Blue, Magenta, Cyan, White,
    BrightBlack, BrightRed, BrightGreen, BrightYellow, BrightBlue, BrightMagenta, BrightCyan, BrightWhite,
    Fixed(u8), Rgb(u8, u8, u8),
}
impl Color {
    fn fg_code(&self) -> String {
        match self {
            Color::Black => "30".into(), Color::Red => "31".into(), Color::Green => "32".into(), Color::Yellow => "33".into(),
            Color::Blue => "34".into(), Color::Magenta => "35".into(), Color::Cyan => "36".into(), Color::White => "37".into(),
            Color::BrightBlack => "38;5;8".into(), Color::BrightRed => "38;5;9".into(), Color::BrightGreen => "38;5;10".into(), Color::BrightYellow => "38;5;11".into(),
            Color::BrightBlue => "38;5;12".into(), Color::BrightMagenta => "38;5;13".into(), Color::BrightCyan => "38;5;14".into(), Color::BrightWhite => "38;5;15".into(),
            Color::Fixed(n) => format!("38;5;{}", n),
            Color::Rgb(r,g,b) => format!("38;2;{};{};{}", r,g,b),
        }
    }
    fn bg_code(&self) -> String {
        match self {
            Color::Black => "40".into(), Color::Red => "41".into(), Color::Green => "42".into(), Color::Yellow => "43".into(),
            Color::Blue => "44".into(), Color::Magenta => "45".into(), Color::Cyan => "46".into(), Color::White => "47".into(),
            Color::BrightBlack => "48;5;8".into(), Color::BrightRed => "48;5;9".into(), Color::BrightGreen => "48;5;10".into(), Color::BrightYellow => "48;5;11".into(),
            Color::BrightBlue => "48;5;12".into(), Color::BrightMagenta => "48;5;13".into(), Color::BrightCyan => "48;5;14".into(), Color::BrightWhite => "48;5;15".into(),
            Color::Fixed(n) => format!("48;5;{}", n),
            Color::Rgb(r,g,b) => format!("48;2;{};{};{}", r,g,b),
        }
    }
}

#[derive(Debug, Clone, Default, PartialEq)]
pub struct Style {
    pub bold: bool, pub dimmed: bool, pub italic: bool, pub underline: bool, pub blink: bool, pub reverse: bool, pub hidden: bool, pub crossed: bool,
    pub fg: Option<Color>, pub bg: Option<Color>,
}
impl Style {
    pub fn parse(code: &str) -> Option<Style> {
        if code.is_empty() { return None; }
        // tokenise u8 codes; any failure -> None
        let mut nums: Vec<u8> = Vec::new();
        for part in code.split(';') {
            if part.is_empty() { return None; }
            match part.parse::<u8>() {
                Ok(v) => nums.push(v),
                Err(_) => return None,
            }
        }
        let mut st = Style::default();
        let mut i = 0;
        while i < nums.len() {
            let c = nums[i];
            match c {
                0 => { st = Style::default(); }
                1 => st.bold = true,
                2 => st.dimmed = true,
                3 => st.italic = true,
                4 => st.underline = true,
                5 => st.blink = true,
                7 => st.reverse = true,
                8 => st.hidden = true,
                9 => st.crossed = true,
                30..=37 => st.fg = Some(match c { 30=>Color::Black,31=>Color::Red,32=>Color::Green,33=>Color::Yellow,34=>Color::Blue,35=>Color::Magenta,36=>Color::Cyan,_=>Color::White }),
                38 | 48 | 58 => {
                    let is_fg = c == 38;
                    let is_bg = c == 48;
                    // extended colour consumes mode + params
                    if i + 1 >= nums.len() { return None; }
                    let mode = nums[i+1];
                    if mode == 5 {
                        if i + 2 >= nums.len() { return None; }
                        let col = Color::Fixed(nums[i+2]);
                        if is_fg { st.fg = Some(col); } else if is_bg { st.bg = Some(col); }
                        i += 2;
                    } else if mode == 2 {
                        if i + 4 >= nums.len() { return None; }
                        let col = Color::Rgb(nums[i+2], nums[i+3], nums[i+4]);
                        if is_fg { st.fg = Some(col); } else if is_bg { st.bg = Some(col); }
                        i += 4;
                    } else {
                        return None;
                    }
                }
                39 => st.fg = None,
                40..=47 => st.bg = Some(match c { 40=>Color::Black,41=>Color::Red,42=>Color::Green,43=>Color::Yellow,44=>Color::Blue,45=>Color::Magenta,46=>Color::Cyan,_=>Color::White }),
                49 => st.bg = None,
                90..=97 => st.fg = Some(match c { 90=>Color::BrightBlack,91=>Color::BrightRed,92=>Color::BrightGreen,93=>Color::BrightYellow,94=>Color::BrightBlue,95=>Color::BrightMagenta,96=>Color::BrightCyan,_=>Color::BrightWhite }),
                100..=107 => st.bg = Some(match c { 100=>Color::BrightBlack,101=>Color::BrightRed,102=>Color::BrightGreen,103=>Color::BrightYellow,104=>Color::BrightBlue,105=>Color::BrightMagenta,106=>Color::BrightCyan,_=>Color::BrightWhite }),
                _ => { /* ignore other codes */ }
            }
            i += 1;
        }
        if st == Style::default() { None } else { Some(st) }
    }
    pub fn prefix(&self) -> String {
        let mut parts: Vec<String> = Vec::new();
        if self.bold { parts.push("1".into()); }
        if self.dimmed { parts.push("2".into()); }
        if self.italic { parts.push("3".into()); }
        if self.underline { parts.push("4".into()); }
        if self.blink { parts.push("5".into()); }
        if self.reverse { parts.push("7".into()); }
        if self.hidden { parts.push("8".into()); }
        if self.crossed { parts.push("9".into()); }
        if let Some(bg) = &self.bg { parts.push(bg.bg_code()); }
        if let Some(fg) = &self.fg { parts.push(fg.fg_code()); }
        if parts.is_empty() { String::new() } else { format!("\x1b[{}m", parts.join(";")) }
    }
    pub fn paint(&self, text: &str) -> String {
        let p = self.prefix();
        if p.is_empty() { text.to_string() } else { format!("{}{}\x1b[0m", p, text) }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Indicator { File, Directory, Symlink, Orphan, Missing, Pipe, Socket, BlockDevice, CharDevice, Executable, Setuid, Setgid, Capability, StickyOtherWritable, OtherWritable, Sticky, MultiHardLink, Door }

#[derive(Debug, Clone)]
