impl LsColors {
    pub fn from_env() -> Self {
        match std::env::var_os("LS_COLORS") {
            None => {
                LsColors { indicators: default_theme_indicators(), suffixes: default_suffixes(), ln_target: false }
            }
            Some(val) => {
                let mut ls = LsColors { indicators: default_indicators(), suffixes: Vec::new(), ln_target: false };
                ls.parse_str(&val.to_string_lossy());
                ls
            }
        }
    }
    fn parse_str(&mut self, s: &str) {
        for part in s.split(':') {
            if part.is_empty() { continue; }
            let Some((key, value)) = part.split_once('=') else { continue };
            if let Some(ind) = indicator_from_key(key) {
                if key == "ln" && value == "target" {
                    self.ln_target = true;
                    self.indicators.insert(ind, None);
                } else {
                    if key == "ln" { self.ln_target = false; }
                    self.indicators.insert(ind, Style::parse(value));
                }
            } else if let Some(suffix) = key.strip_prefix('*') {
                self.suffixes.push((suffix.to_string(), Style::parse(value)));
            } else {
                continue;
            }
        }
    }
    pub fn indicator_style(&self, ind: Indicator) -> Option<&Style> {
        self.indicators.get(&ind).and_then(|o| o.as_ref())
    }
    fn suffix_style(&self, file_name: &str) -> Option<Option<&Style>> {
        // exact case first (reverse order), then case-insensitive (reverse order)
        for (suffix, style) in self.suffixes.iter().rev() {
            if file_name.ends_with(suffix) {
                return Some(style.as_ref());
            }
        }
        let lower = file_name.to_lowercase();
        for (suffix, style) in self.suffixes.iter().rev() {
            if lower.ends_with(&suffix.to_lowercase()) {
                return Some(style.as_ref());
            }
        }
        None
    }
    // style for a path, using effective metadata (already following if appropriate)
    pub fn style_for(&self, path: &std::path::Path, md: &Metadata, file_name: &str) -> Option<&Style> {
        let ft = md.file_type();
        if ft.is_symlink() {
            // orphan?
            let target_exists = std::fs::metadata(path).is_ok();
            if !target_exists {
                if let Some(s) = self.indicator_style(Indicator::Orphan) {
                    return Some(s);
                }
            }
            if self.ln_target { return None; }
            return self.indicator_style(Indicator::Symlink);
        }
        if ft.is_dir() {
            let mode = md.permissions().mode();
            let sticky = mode & 0o1000 != 0;
            let other_write = mode & 0o002 != 0;
            if sticky && other_write {
                if let Some(s) = self.indicator_style(Indicator::StickyOtherWritable) { return Some(s); }
            }
            if other_write {
                if let Some(s) = self.indicator_style(Indicator::OtherWritable) { return Some(s); }
            }
            if sticky {
                if let Some(s) = self.indicator_style(Indicator::Sticky) { return Some(s); }
            }
            return self.indicator_style(Indicator::Directory);
        }
        if ft.is_file() {
            let mode = md.permissions().mode();
            if mode & 0o4000 != 0 {
                if let Some(s) = self.indicator_style(Indicator::Setuid) { return Some(s); }
            }
            if mode & 0o2000 != 0 {
                if let Some(s) = self.indicator_style(Indicator::Setgid) { return Some(s); }
            }
            if mode & 0o111 != 0 {
                if let Some(s) = self.indicator_style(Indicator::Executable) { return Some(s); }
            }
            if md.nlink() > 1 {
                if let Some(s) = self.indicator_style(Indicator::MultiHardLink) { return Some(s); }
            }
            if let Some(found) = self.suffix_style(file_name) {
                return found;
            }
            return self.indicator_style(Indicator::File);
        }
        // other types
        use std::os::unix::fs::FileTypeExt;
        if ft.is_socket() { return self.indicator_style(Indicator::Socket); }
        if ft.is_fifo() { return self.indicator_style(Indicator::Pipe); }
        if ft.is_block_device() { return self.indicator_style(Indicator::BlockDevice); }
        if ft.is_char_device() { return self.indicator_style(Indicator::CharDevice); }
        None
    }
}

fn indicator_from_key(key: &str) -> Option<Indicator> {
    match key {
        "fi" | "no" | "rs" => Some(Indicator::File),
        "di" => Some(Indicator::Directory),
        "ln" => Some(Indicator::Symlink),
        "or" => Some(Indicator::Orphan),
        "mi" => Some(Indicator::Missing),
        "pi" => Some(Indicator::Pipe),
        "so" => Some(Indicator::Socket),
        "bd" => Some(Indicator::BlockDevice),
        "cd" => Some(Indicator::CharDevice),
        "ex" => Some(Indicator::Executable),
        "su" => Some(Indicator::Setuid),
        "sg" => Some(Indicator::Setgid),
        "ca" => Some(Indicator::Capability),
        "tw" => Some(Indicator::StickyOtherWritable),
        "ow" => Some(Indicator::OtherWritable),
        "st" => Some(Indicator::Sticky),
        "mh" => Some(Indicator::MultiHardLink),
        "do" => Some(Indicator::Door),
        _ => None,
    }
}
