use regex::Regex;
use regex_syntax::hir::{Hir, HirKind, Class, Literal};
use regex_syntax::Parser;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum CaseMode { Sensitive, Insensitive }

pub fn hir_has_uppercase(hir: &Hir) -> bool {
    match hir.kind() {
        HirKind::Literal(lit) => {
            let s = String::from_utf8_lossy(&lit.0);
            s.chars().any(|c| c.is_uppercase())
        }
        HirKind::Class(class) => match class {
            Class::Unicode(ranges) => {
                for r in ranges.ranges() {
                    let start = r.start() as u32;
                    let end = r.end() as u32;
                    let mut cp = start;
                    while cp <= end {
                        if let Some(ch) = char::from_u32(cp) {
                            if ch.is_uppercase() { return true; }
                        }
                        if cp == end { break; }
                        cp += 1;
                        // safety: ranges are usually small; but continue
                    }
                }
                false
            }
            Class::Bytes(ranges) => {
                for r in ranges.ranges() {
                    let mut b = r.start();
                    loop {
                        if (b as char).is_uppercase() { return true; }
                        if b == r.end() { break; }
                        b = b.wrapping_add(1);
                    }
                }
                false
            }
        },
        HirKind::Concat(v) | HirKind::Alternation(v) => v.iter().any(hir_has_uppercase),
        HirKind::Capture(cap) => hir_has_uppercase(&cap.sub),
        HirKind::Repetition(rep) => hir_has_uppercase(&rep.sub),
        HirKind::Look(_) => false,
        HirKind::Empty => false,
    }
}

pub fn pattern_has_uppercase(regex_str: &str) -> bool {
    match Parser::new().parse_utf8(regex_str) {
        Ok(hir) => hir_has_uppercase(&hir),
        Err(_) => regex_str.chars().any(|c| c.is_uppercase()),
    }
}

pub fn only_matches_leading_dot(regex_str: &str) -> bool {
    let hir = match Parser::new().parse_utf8(regex_str) {
        Ok(h) => h,
        Err(_) => return false,
    };
    let HirKind::Concat(parts) = hir.kind() else { return false };
    if parts.len() < 2 { return false; }
    // first must be an anchor (Start / StartText / StartLine etc are Look variants in newer regex-syntax?)
    // In regex-syntax 0.8, HirKind::Look for anchors.
    match parts[0].kind() {
        HirKind::Look(_) => {},
        _ => return false,
    }
    match parts[1].kind() {
        HirKind::Literal(lit) => {
            !lit.0.is_empty() && lit.0[0] == b'.'
        }
        HirKind::Class(class) => match class {
            Class::Unicode(ranges) => {
                let rs = ranges.ranges();
                rs.len() == 1 && rs[0].start() == '.' && rs[0].end() == '.'
            }
            Class::Bytes(ranges) => {
                let rs = ranges.ranges();
                rs.len() == 1 && rs[0].start() == b'.' && rs[0].end() == b'.'
            }
        },
        _ => false,
    }
}

pub fn build_regexes(
    patterns_strs: &[String], // regex strings (already glob-converted or escaped if needed)
    insensitive: bool,
    original_patterns_for_error: &[String], // parallel to patterns_strs? not needed
    is_glob: bool,
) -> Result<Vec<Regex>, String> {
    let _ = original_patterns_for_error;
    let _ = is_glob;
    let mut out = Vec::new();
    for p in patterns_strs {
        let re = regex::RegexBuilder::new(p)
            .case_insensitive(insensitive)
            .build();
        match re {
            Ok(r) => out.push(r),
            Err(e) => return Err(format!("{}", e)),
        }
    }
    Ok(out)
}

pub fn glob_to_regex(glob: &str, insensitive: bool) -> Result<String, String> {
    let mut builder = globset::GlobBuilder::new(glob);
    builder.literal_separator(true);
    builder.case_insensitive(insensitive);
    match builder.build() {
        Ok(g) => Ok(g.regex().to_string()),
        Err(e) => Err(format!("{}", e)),
    }
}
