use std::ffi::OsStr;
use std::os::unix::ffi::OsStrExt;
use std::path::{Path, PathBuf};

// placeholder handling

pub const SENTINEL_L: u8 = 0;
pub const SENTINEL_R: u8 = 1;

pub fn escape_template(template: &[u8]) -> Vec<u8> {
    let mut out = Vec::with_capacity(template.len());
    let mut i = 0;
    while i < template.len() {
        if template[i] == b'{' && i + 1 < template.len() && template[i+1] == b'{' {
            out.push(SENTINEL_L);
            i += 2;
        } else if template[i] == b'}' && i + 1 < template.len() && template[i+1] == b'}' {
            out.push(SENTINEL_R);
            i += 2;
        } else {
            out.push(template[i]);
            i += 1;
        }
    }
    out
}

pub fn strip_cwd_prefix_bytes(path: &Path) -> PathBuf {
    // strip a leading "." component if present
    if let Ok(stripped) = path.strip_prefix(".") {
        stripped.to_path_buf()
    } else {
        path.to_path_buf()
    }
}

pub fn path_without_extension(path: &Path) -> PathBuf {
    let stripped = strip_cwd_prefix_bytes(path);
    // Path::with_extension("") behaviour
    let result = stripped.with_extension("");
    // with_extension on e.g. "file." gives "file", on "a.tar.gz" gives "a.tar"
    result
}

pub fn parent_or_dot(path: &Path) -> PathBuf {
    match path.parent() {
        Some(p) => {
            if p.as_os_str().is_empty() { PathBuf::from(".") } else { p.to_path_buf() }
        }
        None => PathBuf::from("."),
    }
}

pub fn placeholder_values(path: &Path, path_separator: &str) -> Vec<(&'static str, Vec<u8>)> {
    // returns values for each token using byte representation, with separator replacement applied to path-like values
    let replace_sep = |bytes: &[u8]| -> Vec<u8> {
        if path_separator == "/" {
            bytes.to_vec()
        } else {
            let mut out = Vec::new();
            for &b in bytes {
                if b == b'/' {
                    out.extend_from_slice(path_separator.as_bytes());
                } else {
                    out.push(b);
                }
            }
            out
        }
    };
    let full = replace_sep(path.as_os_str().as_bytes());
    let basename: Vec<u8> = path.file_name().map(|s| s.as_bytes().to_vec()).unwrap_or_else(|| path.as_os_str().as_bytes().to_vec());
    let parent_path = parent_or_dot(path);
    let parent = replace_sep(parent_path.as_os_str().as_bytes());
    let noext_path = path_without_extension(path);
    let noext = replace_sep(noext_path.as_os_str().as_bytes());
    let basename_noext: Vec<u8> = {
        // file stem of path
        match path.file_stem() {
            Some(s) => s.as_bytes().to_vec(),
            None => basename.clone(),
        }
    };
    vec![
        ("{}", full),
        ("{/}", basename),
        ("{//}", parent),
        ("{.}", noext),
        ("{/.}", basename_noext),
    ]
}

pub fn replace_placeholders(template: &[u8], path: &Path, path_separator: &str) -> (Vec<u8>, bool) {
    let escaped = escape_template(template);
    let values = placeholder_values(path, path_separator);
    // order matters: check longer tokens first
    let tokens: Vec<(&str, &[u8])> = vec![
        ("{/.}", values[4].as_slice()),
        ("{//}", values[2].as_slice()),
        ("{/}", values[1].as_slice()),
        ("{.}", values[3].as_slice()),
        ("{}", values[0].as_slice()),
    ];
    let mut out = Vec::new();
    let mut i = 0;
    let mut found = false;
    while i < escaped.len() {
        let mut matched = false;
        // only try at '{'
        if escaped[i] == b'{' {
            for (tok, val) in &tokens {
                let tb = tok.as_bytes();
                if escaped[i..].starts_with(tb) {
                    out.extend_from_slice(val);
                    i += tb.len();
                    found = true;
                    matched = true;
                    break;
                }
            }
        }
        if !matched {
            out.push(escaped[i]);
            i += 1;
        }
    }
    // restore sentinels
    for b in out.iter_mut() {
        if *b == SENTINEL_L { *b = b'{'; } else if *b == SENTINEL_R { *b = b'}'; }
    }
    (out, found)
}

pub fn replace_placeholders_string(template: &str, path_str: &str, path_separator: &str) -> String {
    // path_str is display string (already separator-replaced?) For format, fd replaces separators in placeholder values.
    // We work on Path from path_str original with '/' separators; caller passes original path.
    // This helper is not used directly; see format implementation in output.
    let _ = (template, path_str, path_separator);
    String::new()
}

pub fn os_to_vec(s: &OsStr) -> Vec<u8> { s.as_bytes().to_vec() }
RS
