    pub max_results: Option<usize>,
    pub cwd: PathBuf,
}

#[derive(Clone)]
pub struct SearchResult {
    pub display_path: PathBuf, // path for output (after absolute/strip)
    pub raw_path: PathBuf,
    pub is_dir: bool,
    pub file_type: Option<fs::FileType>,
}

impl SearchResult {
    pub fn new(raw: &DirEntry, cfg: &Config) -> Self {
        let raw_path = raw.path().to_path_buf();
        let is_dir = raw.file_type().map(|ft| ft.is_dir()).unwrap_or(false);
        let display_path = compute_display_path(&raw_path, cfg, false);
        SearchResult { display_path, raw_path, is_dir, file_type: raw.file_type() }
    }
}

pub fn compute_display_path(raw_path: &Path, cfg: &Config, for_exec: bool) -> PathBuf {
    let _ = for_exec;
    if cfg.absolute {
        absolutize_path(raw_path)
    } else {
        let mut p = raw_path.to_path_buf();
        if cfg.is_implicit_root && should_strip(cfg) {
            if let Ok(stripped) = p.strip_prefix(".") {
                p = stripped.to_path_buf();
            }
        }
        p
    }
}

pub fn should_strip(cfg: &Config) -> bool {
    match cfg.strip_mode {
        StripMode::Always => true,
        StripMode::Never => false,
        StripMode::Auto => {
            // strip unless we're in a mode that needs ./ prefix for safety
            let needs_prefix = cfg.print0 || !cfg.execs.is_empty() || !cfg.exec_batches.is_empty() || cfg.list_details;
            !needs_prefix
        }
    }
}

pub fn absolutize_path(path: &Path) -> PathBuf {
    // canonicalize parent, keep final component (mirrors path-absolutize behaviour observed)
    if let Some(file_name) = path.file_name() {
        if let Some(parent) = path.parent() {
            let parent_abs = if parent.as_os_str().is_empty() {
                std::env::current_dir().unwrap_or_else(|_| PathBuf::from("/"))
            } else if parent.is_absolute() {
                parent.to_path_buf()
            } else {
                match std::env::current_dir() {
                    Ok(cwd) => cwd.join(parent),
                    Err(_) => parent.to_path_buf(),
                }
            };
            if let Ok(canon) = fs::canonicalize(&parent_abs) {
                return canon.join(file_name);
            }
            // fallback lexical
            return lexical_absolute(&parent_abs).join(file_name);
        }
    }
    lexical_absolute(path)
}

fn lexical_absolute(path: &Path) -> PathBuf {
    let abs = if path.is_absolute() {
        path.to_path_buf()
    } else {
        match std::env::current_dir() {
            Ok(cwd) => cwd.join(path),
            Err(_) => path.to_path_buf(),
        }
    };
    // remove CurDir components, keep ParentDir
    let mut out = PathBuf::new();
    for comp in abs.components() {
        use std::path::Component::*;
        match comp {
            CurDir => {},
            _ => out.push(comp.as_os_str()),
        }
    }
    if out.as_os_str().is_empty() { PathBuf::from("/") } else { out }
}

pub fn absolute_for_match(path: &Path, cwd: &Path, cfg: &Config) -> String {
    // path is candidate (absolutized display if cfg.absolute, else raw)
    if cfg.absolute {
        return path.to_string_lossy().into_owned();
    }
    if path.is_absolute() {
        return path.to_string_lossy().into_owned();
    }
    // strip leading ./ if present
    let stripped = match path.strip_prefix(".") {
        Ok(s) => s.to_path_buf(),
        Err(_) => path.to_path_buf(),
    };
    let joined = cwd.join(stripped);
    joined.to_string_lossy().into_owned()
}

fn hostname() -> String {
    let mut buf = vec![0u8; 256];
    let rc = unsafe { libc::gethostname(buf.as_mut_ptr() as *mut libc::c_char, buf.len()) };
    if rc != 0 { return String::new(); }
    let end = buf.iter().position(|&b| b == 0).unwrap_or(buf.len());
    String::from_utf8_lossy(&buf[..end]).into_owned()
}

pub fn hyperlink_url(display_path: &Path, cfg: &Config) -> String {
