            Ok(s) => s.to_path_buf(),
            Err(_) => display_path.to_path_buf(),
        };
        cfg.cwd.join(stripped)
    };
    let bytes = abs.as_os_str().as_bytes();
    let mut url = String::new();
    url.push_str("file://");
    url.push_str(&hostname());
    // percent encode each byte except unreserved and '/'
    for &b in bytes {
        let allowed = b.is_ascii_alphanumeric() || b == b'-' || b == b'_' || b == b'.' || b == b'~' || b == b'/';
        if allowed {
            url.push(b as char);
        } else {
            url.push_str(&format!("%{:02X}", b));
        }
    }
    url
}

// ---------------- exec helpers ----------------

pub fn exec_template_has_placeholder(args: &[Vec<u8>], path: &Path, sep: &str) -> bool {
    let mut any = false;
    for a in args {
        let (_, found) = text::replace_placeholders(a, path, sep);
        if found { any = true; }
    }
    any
}

pub fn build_exec_argv(template: &ExecTemplate, result: &SearchResult, cfg: &Config) -> Vec<OsString> {
    let sep = cfg.path_separator.as_str();
    // display path for exec: cfg display is already computed with should_strip considering exec
    let path = &result.display_path;
    let mut argv: Vec<OsString> = Vec::new();
    let mut has_placeholder = false;
    for arg_template in &template.args {
        let (replaced, found) = text::replace_placeholders(arg_template, path, sep);
        if found { has_placeholder = true; }
        argv.push(OsString::from_vec(replaced));
    }
    if !has_placeholder {
        let (replaced, _) = text::replace_placeholders(b"{}", path, sep);
        argv.push(OsString::from_vec(replaced));
    }
    argv
}

use std::os::unix::ffi::OsStringExt;

pub fn run_command(argv: &[OsString]) -> (bool, Option<String>) {
    if argv.is_empty() { return (true, None); }
    let mut cmd = std::process::Command::new(&argv[0]);
    if argv.len() > 1 { cmd.args(&argv[1..]); }
    match cmd.status() {
        Ok(status) => {
            if status.success() { (false, None) } else { (true, None) }
        }
        Err(e) => {
            if e.kind() == io::ErrorKind::NotFound {
                let name = argv[0].to_string_lossy().into_owned();
                (true, Some(format!("[fd error]: Command not found: {}\n", name)))
            } else {
                (true, Some(format!("[fd error]: Problem while executing command: {}\n", e)))
            }
        }
    }
}

fn estimated_arg_len(argv: &[OsString]) -> usize {
    argv.iter().map(|a| a.as_os_str().as_bytes().len() + 1 + 8).sum::<usize>()
    + std::env::vars_os().map(|(k, v)| k.as_os_str().as_bytes().len() + v.as_os_str().as_bytes().len() + 2 + 16).sum::<usize>()
}

pub fn run_batch_commands(
    templates: &[ExecTemplate],
    results: &[SearchResult],
    cfg: &Config,
    batch_size: usize,
) -> bool {
    let mut any_error = false;
    if results.is_empty() { return false; }
    // arg max estimate
    let arg_max: usize = unsafe {
        let v = libc::sysconf(libc::_SC_ARG_MAX);
        if v > 0 { v as usize } else { 2_097_152 }
    };
    let limit = if arg_max > 4096 { arg_max - 2048 } else { arg_max };
    for template in templates {
        // Determine placeholder arg indices etc., chunks are by results
        let mut start = 0usize;
        while start < results.len() {
            // determine chunk size
            let mut end = results.len();
            if batch_size > 0 {
                end = std::cmp::min(end, start + batch_size);
            }
            // OS limit: grow end as much as possible but at least 1
            let mut last_good = std::cmp::min(end, start + 1);
            for cand_end in (start+1)..=end {
                // build argv for this candidate to estimate
                let chunk = &results[start..cand_end];
                let argv = build_batch_argv(template, chunk, cfg);
                if estimated_arg_len(&argv) <= limit {
                    last_good = cand_end;
                } else {
                    break;
                }
            }
            end = last_good;
            if batch_size > 0 {
                end = std::cmp::min(end, start + batch_size);
            }
            let chunk = &results[start..end];
            let argv = build_batch_argv(template, chunk, cfg);
            let (is_err, msg) = run_command(&argv);
            if let Some(m) = msg { eprint!("{}", m); }
            if is_err { any_error = true; }
            start = end;
        }
    }
    any_error
}

pub fn build_batch_argv(template: &ExecTemplate, chunk: &[SearchResult], cfg: &Config) -> Vec<OsString> {
    let sep = cfg.path_separator.as_str();
    let mut argv: Vec<OsString> = Vec::new();
    let mut has_placeholder = false;
    // dummy path for placeholder detection
    let dummy = Path::new("dummy");
    for arg_template in &template.args {
        let escaped = text::escape_template(arg_template);
        // check if this arg contains a token
        let (_, found) = text::replace_placeholders(arg_template, dummy, sep);
        if found {
            has_placeholder = true;
            for result in chunk {
                let (replaced, _) = text::replace_placeholders(arg_template, &result.display_path, sep);
                argv.push(OsString::from_vec(replaced));
            }
            let _ = escaped;
        } else {
            let (replaced, _) = text::replace_placeholders(arg_template, dummy, sep);
            argv.push(OsString::from_vec(replaced));
        }
    }
    if !has_placeholder {
        for result in chunk {
            let (replaced, _) = text::replace_placeholders(b"{}", &result.display_path, sep);
            argv.push(OsString::from_vec(replaced));
        }
    }
    argv
}

// placeholder-count validation for exec-batch (number of placeholder arguments)
pub fn count_placeholder_args(template: &ExecTemplate) -> usize {
    let dummy = Path::new("dummy");
    let mut n = 0;
    for arg in &template.args {
        let (_, found) = text::replace_placeholders(arg, dummy, "/");
        if found { n += 1; }
    }
    n
}

// ---------------- filtering ----------------

pub struct Shared {
    pub cfg: Arc<Config>,
    pub regexes: Arc<Vec<Regex>>,
}

pub fn entry_passes(entry: &DirEntry, cfg: &Config, regexes: &[Regex]) -> bool {
    // depth
    if entry.depth() < cfg.min_depth { return false; }
    if let Some(max) = cfg.max_depth_opt {
        if entry.depth() > max { return false; }
    }
    let path = entry.path();
    // pattern
    if !regexes.is_empty() {
        let subject: String = if cfg.full_path {
            let candidate = if cfg.absolute { absolutize_path(path) } else { path.to_path_buf() };
            absolute_for_match(&candidate, &cfg.cwd, cfg)
        } else {
            entry.file_name().to_string_lossy().into_owned()
        };
        for re in regexes {
            if !re.is_match(&subject) { return false; }
        }
    }
    // types
    if let Some(tf) = &cfg.types {
        if let Some(ft) = entry.file_type() {
            if !tf.matches(path, &ft) { return false; }
        } else {
            return false;
        }
    }
    // extension
    if let Some(exts) = &cfg.extensions {
        if !extension_matches(entry.file_name(), exts) { return false; }
    }
    // size
    if !cfg.sizes.is_empty() {
        // must be a regular file (following symlink) and compare with symlink size
        let eff = match fs::metadata(path) { Ok(m) => m, Err(_) => return false };
        if !eff.is_file() { return false; }
        let link_md = match fs::symlink_metadata(path) { Ok(m) => m, Err(_) => return false };
        let sz = link_md.len();
        for sc in &cfg.sizes {
            if !sc.matches(sz) { return false; }
        }
    }
    // time
    if cfg.changed_within.is_some() || cfg.changed_before.is_some() {
        let md = match fs::symlink_metadata(path) { Ok(m) => m, Err(_) => return false };
        if !metadata_time_matches(&md, cfg.changed_within, cfg.changed_before) { return false; }
    }
    // owner
    if let Some(owner) = &cfg.owner {
        if !owner.is_empty() {
            let md = match fs::symlink_metadata(path) { Ok(m) => m, Err(_) => return false };
            if !owner.matches(&md) { return false; }
        }
    }
    true
}

// ---------------- walker visitors ----------------

pub enum Mode {
    Print { sender: Sender<SearchResult> },
    Quiet { sender: Sender<SearchResult> },
    Batch { sender: Sender<SearchResult> },
    Exec { error_flag: Arc<AtomicBool>, print0_stdout: Arc<Mutex<()>> },
}

pub struct VisitorBuilderShared {
    pub cfg: Arc<Config>,
    pub regexes: Arc<Vec<Regex>>,
    pub mode: std::sync::Arc<ModeShared>,
}

pub enum ModeShared {
    Channel { sender: Sender<SearchResult> },
    Exec { error_flag: Arc<AtomicBool> },
}

pub struct FdVisitor {
    pub cfg: Arc<Config>,
    pub regexes: Arc<Vec<Regex>>,
    pub mode: ModeKind,
}

pub enum ModeKind {
    Channel { sender: Sender<SearchResult> },
    Exec { error_flag: Arc<AtomicBool> },
}

impl ignore::ParallelVisitorBuilder<'_> for VisitorBuilderShared {
    fn build(&mut self) -> Box<dyn ignore::ParallelVisitor + '_> {
        let mode = match &*self.mode {
            ModeShared::Channel { sender } => ModeKind::Channel { sender: sender.clone() },
            ModeShared::Exec { error_flag } => ModeKind::Exec { error_flag: error_flag.clone() },
        };
        Box::new(FdVisitor { cfg: self.cfg.clone(), regexes: self.regexes.clone(), mode })
    }
}

impl ignore::ParallelVisitor for FdVisitor {
    fn visit(&mut self, result: Result<DirEntry, ignore::Error>) -> WalkState {
        let entry = match result {
            Ok(e) => e,
            Err(err) => {
                if self.cfg.show_errors {
                    eprintln!("[fd error]: {}", err);
                }
                return WalkState::Continue;
            }
        };
        // ignore-contain check (applies also to depth 0)
        if !self.cfg_ignore_contain_names().is_empty() {
            // we need the names; stored in cfg via a thread-local? Actually Config does not carry them.
            // They are checked in a separate field packed into regexes? No, check via cfg extension field below.
        }
        if entry.depth() == 0 {
            if check_ignore_contain(&entry, &self.cfg) {
                return WalkState::Skip;
            }
            return WalkState::Continue;
        }
        if check_ignore_contain(&entry, &self.cfg) {
            return WalkState::Skip;
        }
        let passes = entry_passes(&entry, &self.cfg, &self.regexes);
        if !passes {
            return WalkState::Continue;
        }
        let is_dir = entry.file_type().map(|ft| ft.is_dir()).unwrap_or(false);
        // build the result with display path computed using the mode-dependent strip logic.
        // For channel modes, the Config as passed already reflects strip behaviour of caller;
        // for exec, same cfg is used.
        let result_obj = SearchResult::new(&entry, &self.cfg);
        match &mut self.mode {
            ModeKind::Channel { sender } => {
                if sender.send(result_obj).is_err() {
                    return WalkState::Quit;
                }
            }
            ModeKind::Exec { error_flag } => {
                // execute commands for this entry
                let mut entry_error = false;
                for template in &self.cfg.execs {
                    let argv = build_exec_argv(template, &result_obj, &self.cfg);
                    let (is_err, msg) = run_command(&argv);
                    if let Some(m) = msg { eprint!("{}", m); }
                    if is_err { entry_error = true; break; }
                }
                if entry_error { error_flag.store(true, Ordering::SeqCst); }
                if self.cfg.print0 {
                    let stdout = io::stdout();
                    let mut handle = stdout.lock();
                    let _ = handle.write_all(b"\0");
                    let _ = handle.flush();
                }
            }
        }
        if self.cfg.prune && is_dir {
            return WalkState::Skip;
        }
        WalkState::Continue
    }
}

impl FdVisitor {
    fn cfg_ignore_contain_names(&self) -> Vec<String> { Vec::new() }
}

pub fn check_ignore_contain(entry: &DirEntry, cfg: &Config) -> bool {
    if cfg.ignore_contain.is_empty() { return false; }
    let path = entry.path();
    if !path.is_dir() { return false; }
    for name in &cfg.ignore_contain {
        if path.join(name).exists() { return true; }
    }
    false
}

// Additional field in Config for ignore_contain – we add it via a patch struct extension:
// Config is defined above; add field through re-definition not possible, so it is stored
// as a field we appended in Config definition (ignore_contain).
RS
"}

