    } else {
        let mut p = raw_path.to_path_buf();
        if cfg.is_implicit_root && should_strip(cfg) {
            if let Ok(stripped) = p.strip_prefix(".") {
                p = stripped.to_path_buf();
            }
        }
        p
    }
