use std::ffi::OsStr;
use std::io::{self, Write};
use std::os::unix::ffi::OsStrExt;
use std::path::Path;

use crate::app::{Config, SearchResult, hyperlink_url};
use crate::lscolors::Indicator;
use crate::text;

// returns Err(()) on write error
pub fn print_result(writer: &mut dyn Write, result: &SearchResult, cfg: &Config) -> Result<(), ()> {
    // build content bytes (without terminator)
    let content: Vec<u8> = if let Some(fmt) = &cfg.format_template {
        // format template, using lossy string path
        format_result(fmt, result, cfg).into_bytes()
    } else if cfg.color_enabled {
        colored_path_bytes(result, cfg)
    } else {
        plain_path_bytes(result, cfg)
    };
    if cfg.hyperlink_enabled {
        let url = hyperlink_url(&result.display_path, cfg);
        writer.write_all(format!("\x1b]8;;{}\x1b\\", url).as_bytes()).map_err(|_| ())?;
        writer.write_all(&content).map_err(|_| ())?;
        writer.write_all(b"\x1b]8;;\x1b\\").map_err(|_| ())?;
    } else {
        writer.write_all(&content).map_err(|_| ())?;
    }
    if cfg.print0 {
        writer.write_all(b"\0").map_err(|_| ())?;
    } else {
        writer.write_all(b"\n").map_err(|_| ())?;
    }
    Ok(())
}

fn replace_separator_str(s: &str, cfg: &Config) -> String {
    if cfg.path_separator == "/" {
        s.to_string()
    } else {
        s.replace('/', &cfg.path_separator)
    }
}

pub fn plain_path_bytes(result: &SearchResult, cfg: &Config) -> Vec<u8> {
    let mut out = Vec::new();
    let path_bytes = result.display_path.as_os_str().as_bytes();
    if cfg.path_separator == "/" {
        out.extend_from_slice(path_bytes);
    } else {
        for &b in path_bytes {
            if b == b'/' {
                out.extend_from_slice(cfg.path_separator.as_bytes());
            } else {
                out.push(b);
            }
        }
    }
    if result.is_dir {
        out.extend_from_slice(cfg.path_separator.as_bytes());
    }
    out
}

pub fn colored_path_bytes(result: &SearchResult, cfg: &Config) -> Vec<u8> {
    let ls = match &cfg.lscolors { Some(l) => l.clone(), None => return plain_path_bytes(result, cfg) };
    // display string lossy
    let mut display = result.display_path.to_string_lossy().into_owned();
    if result.is_dir {
        // trailing slash handled separately below, do not include in display for colouring name
    }
    // split at last '/'
    let (parent_part, file_part) = match display.rfind('/') {
        Some(idx) => (Some(display[..=idx].to_string()), display[idx+1..].to_string()),
        None => (None, display.clone()),
    };
    let mut out = String::new();
    // parent part, painted with Directory indicator
    if let Some(parent) = parent_part {
        let parent_disp = replace_separator_str(&parent, cfg);
        if let Some(style) = ls.indicator_style(Indicator::Directory) {
            out.push_str(&style.paint(&parent_disp));
        } else {
            out.push_str(&parent_disp);
        }
    }
    // final component, using effective metadata of raw path
    let md_opt = crate::filter::effective_metadata(&result.raw_path);
    let file_disp = replace_separator_str(&file_part, cfg);
    let painted_file = if let Some(md) = md_opt {
        if let Some(style) = ls.style_for(&result.raw_path, &md, &file_part) {
            style.paint(&file_disp)
        } else {
            file_disp.clone()
        }
    } else {
        file_disp.clone()
    };
    out.push_str(&painted_file);
    if result.is_dir {
        let sep = cfg.path_separator.clone();
        if let Some(style) = ls.indicator_style(Indicator::Directory) {
            out.push_str(&style.paint(&sep));
        } else {
            out.push_str(&sep);
        }
    }
    let _ = display;
    out.into_bytes()
}

pub fn format_result(fmt: &str, result: &SearchResult, cfg: &Config) -> String {
    // placeholder replacement on string, with separator substitution
    // work on display path (Path) but placeholders need separator replacement
    let path = &result.display_path;
    // replace using bytes then convert lossy
    let (replaced, _) = text::replace_placeholders(fmt.as_bytes(), path, &cfg.path_separator);
    String::from_utf8_lossy(&replaced).into_owned()
}
RS
"}

