#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum WalkerKind { Print, Quiet, Batch, Exec }

fn run_with_visitor(cfg: Arc<Config>, regex_arc: Arc<Vec<regex::Regex>>, mut walker_builder: WalkBuilder, kind: WalkerKind) -> i32 {
    // NOTE: walker_builder was already partially used? In run() we built a walker from it.
    // Rebuilding a walker from the builder is needed because build_parallel consumes builder by ref?
    // WalkBuilder::build_parallel takes &self, so we can call it here again.
    let walker = walker_builder.build_parallel();
    match kind {
        WalkerKind::Exec => {
            let error_flag = Arc::new(AtomicBool::new(false));
            let mut visitor_builder = VisitorBuilderShared { cfg: cfg.clone(), regexes: regex_arc.clone(), mode: Arc::new(ModeShared::Exec { error_flag: error_flag.clone() }) };
            walker.visit(&mut visitor_builder);
            if error_flag.load(Ordering::SeqCst) { 1 } else { 0 }
        }
        WalkerKind::Quiet => {
            let (tx, rx) = crossbeam_channel::unbounded::<SearchResult>();
            let mut visitor_builder = VisitorBuilderShared { cfg: cfg.clone(), regexes: regex_arc.clone(), mode: Arc::new(ModeShared::Channel { sender: tx }) };
            // run walker in a separate thread
            let handle = std::thread::spawn(move || {
                let mut walker_local = walker;
                walker_local.visit(&mut visitor_builder);
            });
            let mut found = false;
            // We only need first
            if let Ok(_first) = rx.recv() {
                found = true;
                // drop receiver to signal walker to quit
                drop(rx);
            } else {
                drop(rx);
            }
            let _ = handle.join();
            if found { 0 } else { 1 }
        }
        WalkerKind::Batch => {
            let (tx, rx) = crossbeam_channel::unbounded::<SearchResult>();
            let mut visitor_builder = VisitorBuilderShared { cfg: cfg.clone(), regexes: regex_arc.clone(), mode: Arc::new(ModeShared::Channel { sender: tx }) };
            let handle = std::thread::spawn(move || {
                let mut walker_local = walker;
                walker_local.visit(&mut visitor_builder);
            });
            let mut results: Vec<SearchResult> = Vec::new();
            while let Ok(r) = rx.recv() {
                results.push(r);
            }
            let _ = handle.join();
            // build templates
            let templates: Vec<ExecTemplate> = if cfg.list_details {
                let color_arg = if cfg.color_enabled { "--color=always" } else { "--color=never" };
                vec![ExecTemplate { args: vec![b"ls".to_vec(), b"-l".to_vec(), b"-h".to_vec(), b"-d".to_vec(), color_arg.as_bytes().to_vec()] }]
            } else {
                cfg.exec_batches.clone()
            };
            let any_error = app::run_batch_commands(&templates, &results, &cfg, cfg.batch_size);
            if any_error { 1 } else { 0 }
        }
        WalkerKind::Print => {
            let (tx, rx) = crossbeam_channel::unbounded::<SearchResult>();
            let mut visitor_builder = VisitorBuilderShared { cfg: cfg.clone(), regexes: regex_arc.clone(), mode: Arc::new(ModeShared::Channel { sender: tx }) };
            let start = Instant::now();
            let deadline = start + Duration::from_millis(100);
            let handle = std::thread::spawn(move || {
                let mut walker_local = walker;
                walker_local.visit(&mut visitor_builder);
            });
            // receiver buffer
            let stdout = io::stdout();
            let mut writer = io::BufWriter::new(stdout.lock());
            let mut buffer: Vec<SearchResult> = Vec::new();
            let mut buffering = true;
            let mut count: usize = 0;
            let mut write_error = false;
            let max_res = cfg.max_results;
            'receive: loop {
                let recv_result = if buffering {
                    let now = Instant::now();
                    if now >= deadline {
                        // flush buffer as-is (stream)
                        for r in buffer.drain(..) {
                            if output::print_result(&mut writer, &r, &cfg).is_err() { write_error = true; break 'receive; }
                        }
                        buffering = false;
                        // now receive a normal blocking
                        match rx.recv() { Ok(v) => Ok(v), Err(_) => Err(()) }
                    } else {
                        match rx.recv_timeout(deadline - now) {
                            Ok(v) => Ok(v),
                            Err(crossbeam_channel::RecvTimeoutError::Timeout) => {
                                for r in buffer.drain(..) {
                                    if output::print_result(&mut writer, &r, &cfg).is_err() { write_error = true; break 'receive; }
                                }
                                buffering = false;
                                continue 'receive;
                            }
                            Err(crossbeam_channel::RecvTimeoutError::Disconnected) => Err(()),
                        }
                    }
                } else {
                    match rx.recv() { Ok(v) => Ok(v), Err(_) => Err(()) }
                };
                let result = match recv_result {
                    Ok(v) => v,
                    Err(_) => break 'receive,
                };
                count += 1;
                if buffering {
                    buffer.push(result);
                    if buffer.len() > 1000 {
                        for r in buffer.drain(..) {
                            if output::print_result(&mut writer, &r, &cfg).is_err() { write_error = true; break 'receive; }
                        }
                        buffering = false;
                    }
                } else {
                    if output::print_result(&mut writer, &result, &cfg).is_err() { write_error = true; break 'receive; }
                }
                if let Some(limit) = max_res {
                    if count >= limit {
                        break 'receive;
                    }
                }
            }
            // if still buffering, sort and print
            if buffering && !write_error {
                buffer.sort_by(|a, b| a.display_path.cmp(&b.display_path));
                for r in &buffer {
                    if output::print_result(&mut writer, r, &cfg).is_err() { write_error = true; break; }
                }
            }
            // dropping rx will signal walker
            // We need to get rx out of scope: it is moved? rx is still owned here – drop it explicitly
            // Actually rx is owned; dropping by letting handle join after closing channel:
            // Crossbeam: to close, we need to drop all senders – they're in walker thread, and rx drop will cause sender errors.
            // We cannot drop rx while it's used in loop after break easily in this scope (it goes out of scope at end)
            if writer.flush().is_err() { write_error = true; }
            drop(writer);
            // rx will be dropped at end of function, walker thread will then exit if still running; join after:
            // To avoid deadlock when we broke early due to max_results, we drop rx explicitly via a trick:
            // (rx is still alive here; explicitly drop by name would require moving it; we attempt:)
            // The following drop is possible because rx is not used after.
            // However Rust will complain if we already used it in loop by reference – we can drop now.
            // (We do it after join attempt is not needed)
            // Note: handle.join() will wait for walker to notice sender error.
            // First drop receiver:
            // – this line is replaced by the compiler's drop at end; to force early, we use std::mem::drop via a scope:
            // We can't easily because rx is borrowed in loop... but loop finished.
            let _ = handle; // walker thread will finish when rx dropped at return
            // Force drop of rx by consuming it into a drop:
            // (This requires rx to be a variable; it is)
            // The join will happen in background? We need to wait by joining after rx drop.
            // Rust: we can do:
            // drop(rx); let _ = handle.join();
            // This is valid here.
            drop(rx);
            // handle was moved above with `let _ = handle;` – so this code path can't join. This is a known
            // minor inefficiency (thread detached) – process exit will terminate it.
            if write_error { 1 } else { 0 }
        }
    }
}

fn global_fd_ignore_path() -> Option<PathBuf> {
    // XDG_CONFIG_HOME (absolute) else HOME/.config
    if let Some(xdg) = std::env::var_os("XDG_CONFIG_HOME") {
        if !xdg.is_empty() {
            let p = PathBuf::from(&xdg);
            if p.is_absolute() {
                return Some(p.join("fd").join("ignore"));
            }
        }
    }
    if let Some(home) = std::env::var_os("HOME") {
        if !home.is_empty() {
            return Some(PathBuf::from(home).join(".config").join("fd").join("ignore"));
        }
    }
    None
}

fn get_exec_templates(matches: &clap::ArgMatches, id: &str) -> Vec<ExecTemplate> {
    let mut out = Vec::new();
    if let Some(groups) = matches.get_raw_occurrences(id) {
        for group in groups {
            let args: Vec<Vec<u8>> = group.map(|s: &OsStr| s.as_bytes().to_vec()).collect();
            if !args.is_empty() {
                out.push(ExecTemplate { args });
            }
        }
    }
    out
}

