    if let Some(p) = &pattern_opt { all_user_patterns.push(p.clone()); }

    // Determine case sensitivity
    // first convert each pattern to its regex string (for glob/fixed) without case flag,
    // then check uppercase on those regex strings, except fixed where we check raw literal.
    let mut regex_strs: Vec<String> = Vec::new();
    // For glob errors, need to report the original glob pattern.
    // We build regex strings in AND-first order.
    for pat in &all_user_patterns {
        if fixed {
            regex_strs.push(regex::escape(pat));
        } else if is_glob {
            // glob conversion needs provisional case decision? fd builds glob regex with
            // case_insensitive based on final decision, which we do not know yet.
            // Two-pass: first convert with insensitive=false to inspect uppercase,
            // then reconvert later. For now store with false.
            match pattern::glob_to_regex(pat, false) {
                Ok(r) => regex_strs.push(r),
                Err(e) => {
                    eprint_fd(&format!("error parsing glob '{}': {}\n", pat, e));
                    return 1;
                }
            }
        } else {
            regex_strs.push(pat.clone());
        }
    }
    let insensitive: bool = match case_mode_explicit {
        Some(sensitive) => !sensitive,
        None => {
            // smart case: insensitive unless any (converted) pattern has uppercase
            let any_upper = regex_strs.iter().any(|r| pattern::pattern_has_uppercase(r));
            !any_upper
        }
    };
    // If glob, redo conversion with correct insensitivity
    if is_glob && !fixed {
        regex_strs.clear();
        for pat in &all_user_patterns {
            match pattern::glob_to_regex(pat, insensitive) {
                Ok(r) => regex_strs.push(r),
                Err(e) => {
                    eprint_fd(&format!("error parsing glob '{}': {}\n", pat, e));
                    return 1;
                }
            }
        }
    }
    // Build regexes (for fixed/glob the regex builder should NOT set case_insensitive again
    // if glob already encoded it; but setting it again is consistent. For fixed, we need it.)
    let pattern_regexes: Vec<regex::Regex> = {
        let mut out = Vec::new();
        for (idx, rs) in regex_strs.iter().enumerate() {
            let mut builder = regex::RegexBuilder::new(rs);
            if !is_glob {
                builder.case_insensitive(insensitive);
            }
            match builder.build() {
                Ok(re) => out.push(re),
                Err(e) => {
                    if is_glob {
                        // glob regex should not fail
                        eprint_fd(&format!("{}\n", e));
                    } else if fixed {
                        eprint_fd(&format!("{}\n", e));
                    } else {
                        eprint_fd(&format!("{}\n\nNote: You can use the '--fixed-strings' option to search for a literal string instead of a regular expression. Alternatively, you can also use the '--glob' option to match on a glob pattern.\n", e));
                    }
                    return 1;
                }
            }
        }
        out
    };

    // ---------- hidden / ignore flags ----------
    let hidden_flag = matches.get_flag("hidden");
    let no_hidden_flag = matches.get_flag("no-hidden");
    let unrestricted_count = matches.get_count("unrestricted");
    let show_hidden = hidden_flag || unrestricted_count > 0;
    let no_ignore_flag = matches.get_flag("no-ignore");
    let no_ignore_all = no_ignore_flag || unrestricted_count > 0;
    let no_ignore_vcs_flag = matches.get_flag("no-ignore-vcs");
    let no_ignore_vcs = no_ignore_vcs_flag || no_ignore_all;
    let no_require_git_flag = matches.get_flag("no-require-git");
    let no_ignore_parent_flag = matches.get_flag("no-ignore-parent");

    // leading-dot check
    if !show_hidden {
        for rs in &regex_strs {
            if pattern::only_matches_leading_dot(rs) {
                eprint_fd("The pattern(s) seems to only match files with a leading dot, but hidden files are filtered by default. Consider adding -H/--hidden to search hidden files as well or adjust your search pattern(s).\n");
                return 1;
            }
        }
    }

    // ---------- exclude / overrides ----------
    let exclude_patterns: Vec<String> = matches.get_many::<String>("exclude").map(|v| v.cloned().collect()).unwrap_or_default();
    let overrides_opt = if !exclude_patterns.is_empty() {
        let mut builder = OverrideBuilder::new(&search_paths[0]);
        for pat in &exclude_patterns {
            if let Err(e) = builder.add(pat) {
                eprint_fd(&format!("Malformed exclude pattern: {}\n", e));
                return 1;
            }
        }
        match builder.build() {
            Ok(o) => Some(o),
            Err(e) => {
                eprint_fd(&format!("Malformed exclude pattern: {}\n", e));
                return 1;
            }
        }
    } else { None };

    // ---------- other config ----------
    let absolute_flag = matches.get_flag("absolute-path");
    let follow_flag = matches.get_flag("follow");
    let list_details = matches.get_flag("list-details");
    let print0 = matches.get_flag("print0");
    let prune = matches.get_flag("prune");
    let show_errors = matches.get_flag("show-errors");
    let quiet = matches.get_flag("quiet");

    let max_depth_opt: Option<usize> = matches.get_one::<usize>("exact-depth").cloned().or_else(|| matches.get_one::<usize>("max-depth").cloned());
    let min_depth_val: usize = matches.get_one::<usize>("exact-depth").cloned().or_else(|| matches.get_one::<usize>("min-depth").cloned()).unwrap_or(0);

    let type_vals: Vec<String> = matches.get_many::<String>("type").map(|v| v.cloned().collect()).unwrap_or_default();
    let types_opt = if type_vals.is_empty() { None } else { Some(TypeFilter::from_values(&type_vals)) };

    let ext_vals: Vec<String> = matches.get_many::<String>("extension").map(|v| v.cloned().collect()).unwrap_or_default();
    let extensions_opt = if ext_vals.is_empty() { None } else { Some(ext_vals.iter().map(|e| normalize_extension(e)).collect::<Vec<_>>()) };

    let size_vals: Vec<SizeConstraint> = matches.get_many::<SizeConstraint>("size").map(|v| v.cloned().collect()).unwrap_or_default();
    let owner_opt: Option<OwnerFilter> = matches.get_one::<OwnerFilter>("owner").cloned();

    let format_template: Option<String> = matches.get_one::<String>("format").cloned();
    let batch_size_val: usize = matches.get_one::<usize>("batch-size").cloned().unwrap_or(0);
    let threads_val: Option<usize> = matches.get_one::<std::num::NonZeroUsize>("threads").map(|v| v.get());
    let threads_effective: usize = threads_val.unwrap_or_else(|| std::thread::available_parallelism().map(|v| v.get()).unwrap_or(1));

    // max-results / -1
    let max_results_opt: Option<usize> = {
        let has_one = matches.get_flag("max-one-result");
        let mr = matches.get_one::<usize>("max-results").cloned();
        let chosen = if has_one && mr.is_some() {
            let one_idx = matches.index_of("max-one-result").unwrap_or(0);
            let mr_idx = matches.index_of("max-results").unwrap_or(0);
            if one_idx > mr_idx { Some(1) } else { mr }
        } else if has_one { Some(1) } else { mr };
        match chosen { Some(0) => None, other => other }
    };

    let color_when = match matches.get_one::<String>("color").map(|s| s.as_str()) {
        Some("always") => ColorWhen::Always,
        Some("never") => ColorWhen::Never,
        _ => ColorWhen::Auto,
    };
    let hyperlink_when = match matches.get_one::<String>("hyperlink").map(|s| s.as_str()) {
        Some("always") => HyperlinkWhen::Always,
        Some("auto") => HyperlinkWhen::Auto,
        _ => HyperlinkWhen::Never,
    };
    let strip_mode = match matches.get_one::<String>("strip-cwd-prefix").map(|s| s.as_str()) {
        Some("always") => StripMode::Always,
        Some("never") => StripMode::Never,
        Some("auto") => StripMode::Auto,
        _ => StripMode::Auto,
    };
    let path_separator: String = matches.get_one::<String>("path-separator").cloned().unwrap_or_else(|| "/".to_string());

    // colours
    let stdout_is_tty = io::stdout().is_terminal();
    let no_color_set = std::env::var_os("NO_COLOR").map(|v| !v.is_empty()).unwrap_or(false);
    let color_enabled = match color_when {
        ColorWhen::Always => true,
        ColorWhen::Never => false,
        ColorWhen::Auto => stdout_is_tty && !no_color_set,
    };
    let hyperlink_enabled = match hyperlink_when {
        HyperlinkWhen::Always => true,
        HyperlinkWhen::Never => false,
        HyperlinkWhen::Auto => color_enabled,
    };
    let lscolors_arc = if color_enabled { Some(Arc::new(lscolors::LsColors::from_env())) } else { None };

    // ignore-contain
    let ignore_contain_vals: Vec<String> = matches.get_many::<String>("ignore-contain").map(|v| v.cloned().collect()).unwrap_or_default();

    // ----- construct Config for walker -----
    // Temporary config without regexes moved? We keep regex vec clone into Arc.
    let regex_arc = Arc::new(pattern_regexes);
    let cfg = Arc::new(Config {
        pattern_regexes: Vec::new(), // unused in Config (regexes passed separately)
        pattern_strs_for_dot: Vec::new(),
        full_path: matches.get_flag("full-path"),
        absolute: absolute_flag,
        is_implicit_root,
        strip_mode,
        print0,
        prune,
        min_depth: min_depth_val,
        max_depth_opt,
        types: types_opt,
        extensions: extensions_opt,
        sizes: size_vals,
        changed_within,
        changed_before,
        owner: owner_opt,
        format_template: format_template.clone(),
        execs: exec_templates.clone(),
        exec_batches: exec_batch_templates.clone(),
        list_details,
        batch_size: batch_size_val,
        show_errors,
        path_separator: path_separator.clone(),
        color_when,
        hyperlink_when,
        lscolors: lscolors_arc.clone(),
        color_enabled,
        hyperlink_enabled,
        quiet,
        max_results: max_results_opt,
        cwd: cwd.clone(),
        ignore_contain: ignore_contain_vals.clone(),
    });

    // ---------- walker builder ----------
    let mut walker_builder = WalkBuilder::new(&search_paths[0]);
    for p in &search_paths[1..] { walker_builder.add(p); }
    walker_builder
        .hidden(!show_hidden)
        .ignore(!no_ignore_all)
        .git_ignore(!no_ignore_vcs)
        .git_global(!no_ignore_vcs)
        .git_exclude(!no_ignore_vcs)
        .parents(!no_ignore_parent_flag)
        .require_git(!no_require_git_flag)
        .follow_links(follow_flag)
        .same_file_system(matches.get_flag("one-file-system"))
        .threads(threads_effective);
    if let Some(maxd) = max_depth_opt {
        walker_builder.max_depth(Some(maxd));
    }
    walker_builder.add_custom_ignore_filename(".fdignore");
    // global fd ignore
    if !no_ignore_all {
        if let Some(global_path) = global_fd_ignore_path() {
            if global_path.is_file() {
                if let Some(err) = walker_builder.add_ignore(&global_path) {
                    eprint_fd(&format!("Malformed pattern in global ignore file. {}\n", err));
                }
            }
        }
    }
    // custom ignore files
    if let Some(ignore_files) = matches.get_many::<PathBuf>("ignore-file") {
        for f in ignore_files {
            if let Some(err) = walker_builder.add_ignore(f) {
                eprint_fd(&format!("Malformed pattern in custom ignore file. {}\n", err));
            }
        }
    }
    if let Some(ov) = overrides_opt {
        walker_builder.overrides(ov);
    }

    let walker = walker_builder.build_parallel();

    // ---------- execution modes ----------
    if quiet {
        // receiver: first match -> 0, else 1
        let (tx, rx) = crossbeam_channel::unbounded::<SearchResult>();
        let cfg2 = cfg.clone();
        let regex2 = regex_arc.clone();
        let builder_shared = VisitorBuilderShared { cfg: cfg2, regexes: regex2, mode: Arc::new(ModeShared::Channel { sender: tx }) };
        let walker_thread = std::thread::spawn(move || {
            walker.run(|| {
                // this closure form is not usable; we use visit instead below
                Box::new(|_| ignore::WalkState::Continue)
            });
        });
        // Actually WalkParallel::run expects a factory; we have a custom visitor, so we need to use visit API.
        // To avoid confusion, the above thread will be dropped – we instead run visit in the current scope
        // if the channel approach fails. (This branch is reimplemented below.)
        let _ = walker_thread;
        let _ = rx;
        // Fallthrough to visit-based implementation:
        return run_with_visitor(cfg, regex_arc, walker_builder, WalkerKind::Quiet);
    }

    if !exec_templates.is_empty() {
        return run_with_visitor(cfg, regex_arc, walker_builder, WalkerKind::Exec);
    }

    if list_details || !exec_batch_templates.is_empty() {
        return run_with_visitor(cfg, regex_arc, walker_builder, WalkerKind::Batch);
    }

    return run_with_visitor(cfg, regex_arc, walker_builder, WalkerKind::Print);
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum WalkerKind { Print, Quiet, Batch, Exec }

fn run_with_visitor(cfg: Arc<Config>, regex_arc: Arc<Vec<regex::Regex>>, mut walker_builder: WalkBuilder, kind: WalkerKind) -> i32 {
    // NOTE: walker_builder was already partially used? In run() we built a walker from it.
    // Rebuilding a walker from the builder is needed because build_parallel consumes builder by ref?
    // WalkBuilder::build_parallel takes &self, so we can call it here again.
    let walker = walker_builder.build_parallel();
    match kind {
        WalkerKind::Exec => {
            let error_flag = Arc::new(AtomicBool::new(false));
            let mut visitor_builder = VisitorBuilderShared { cfg: cfg.clone(), regexes: regex_arc.clone(), mode: Arc::new(ModeShared::Exec { error_flag: error_flag.clone() }) };
            walker.visit(&mut visitor_builder);
            if error_flag.load(Ordering::SeqCst) { 1 } else { 0 }
        }
        WalkerKind::Quiet => {
            let (tx, rx) = crossbeam_channel::unbounded::<SearchResult>();
            let mut visitor_builder = VisitorBuilderShared { cfg: cfg.clone(), regexes: regex_arc.clone(), mode: Arc::new(ModeShared::Channel { sender: tx }) };
            // run walker in a separate thread
            let handle = std::thread::spawn(move || {
                let mut walker_local = walker;
                walker_local.visit(&mut visitor_builder);
            });
            let mut found = false;
            // We only need first
            if let Ok(_first) = rx.recv() {
                found = true;
                // drop receiver to signal walker to quit
                drop(rx);
            } else {
                drop(rx);
            }
            let _ = handle.join();
            if found { 0 } else { 1 }
        }
        WalkerKind::Batch => {
            let (tx, rx) = crossbeam_channel::unbounded::<SearchResult>();
            let mut visitor_builder = VisitorBuilderShared { cfg: cfg.clone(), regexes: regex_arc.clone(), mode: Arc::new(ModeShared::Channel { sender: tx }) };
            let handle = std::thread::spawn(move || {
                let mut walker_local = walker;
                walker_local.visit(&mut visitor_builder);
            });
            let mut results: Vec<SearchResult> = Vec::new();
            while let Ok(r) = rx.recv() {
                results.push(r);
            }
            let _ = handle.join();
            // build templates
            let templates: Vec<ExecTemplate> = if cfg.list_details {
                let color_arg = if cfg.color_enabled { "--color=always" } else { "--color=never" };
                vec![ExecTemplate { args: vec![b"ls".to_vec(), b"-l".to_vec(), b"-h".to_vec(), b"-d".to_vec(), color_arg.as_bytes().to_vec()] }]
            } else {
                cfg.exec_batches.clone()
            };
            let any_error = app::run_batch_commands(&templates, &results, &cfg, cfg.batch_size);
            if any_error { 1 } else { 0 }
        }
        WalkerKind::Print => {
            let (tx, rx) = crossbeam_channel::unbounded::<SearchResult>();
            let mut visitor_builder = VisitorBuilderShared { cfg: cfg.clone(), regexes: regex_arc.clone(), mode: Arc::new(ModeShared::Channel { sender: tx }) };
            let start = Instant::now();
            let deadline = start + Duration::from_millis(100);
            let handle = std::thread::spawn(move || {
                let mut walker_local = walker;
                walker_local.visit(&mut visitor_builder);
            });
            // receiver buffer
            let stdout = io::stdout();
            let mut writer = io::BufWriter::new(stdout.lock());
            let mut buffer: Vec<SearchResult> = Vec::new();
            let mut buffering = true;
            let mut count: usize = 0;
            let mut write_error = false;
            let max_res = cfg.max_results;
            'receive: loop {
                let recv_result = if buffering {
                    let now = Instant::now();
                    if now >= deadline {
                        // flush buffer as-is (stream)
                        for r in buffer.drain(..) {
                            if output::print_result(&mut writer, &r, &cfg).is_err() { write_error = true; break 'receive; }
                        }
                        buffering = false;
                        // now receive a normal blocking
                        match rx.recv() { Ok(v) => Ok(v), Err(_) => Err(()) }
                    } else {
                        match rx.recv_timeout(deadline - now) {
                            Ok(v) => Ok(v),
                            Err(crossbeam_channel::RecvTimeoutError::Timeout) => {
                                for r in buffer.drain(..) {
                                    if output::print_result(&mut writer, &r, &cfg).is_err() { write_error = true; break 'receive; }
                                }
                                buffering = false;
                                continue 'receive;
                            }
                            Err(crossbeam_channel::RecvTimeoutError::Disconnected) => Err(()),
                        }
                    }
                } else {
                    match rx.recv() { Ok(v) => Ok(v), Err(_) => Err(()) }
                };
                let result = match recv_result {
                    Ok(v) => v,
                    Err(_) => break 'receive,
                };
                count += 1;
                if buffering {
                    buffer.push(result);
                    if buffer.len() > 1000 {
                        for r in buffer.drain(..) {
                            if output::print_result(&mut writer, &r, &cfg).is_err() { write_error = true; break 'receive; }
                        }
                        buffering = false;
                    }
                } else {
                    if output::print_result(&mut writer, &result, &cfg).is_err() { write_error = true; break 'receive; }
                }
                if let Some(limit) = max_res {
                    if count >= limit {
                        break 'receive;
                    }
                }
            }
            // if still buffering, sort and print
            if buffering && !write_error {
                buffer.sort_by(|a, b| a.display_path.cmp(&b.display_path));
                for r in &buffer {
                    if output::print_result(&mut writer, r, &cfg).is_err() { write_error = true; break; }
                }
            }
            // dropping rx will signal walker
            // We need to get rx out of scope: it is moved? rx is still owned here – drop it explicitly
            // Actually rx is owned; dropping by letting handle join after closing channel:
            // Crossbeam: to close, we need to drop all senders – they're in walker thread, and rx drop will cause sender errors.
            // We cannot drop rx while it's used in loop after break easily in this scope (it goes out of scope at end)
            if writer.flush().is_err() { write_error = true; }
            drop(writer);
            // rx will be dropped at end of function, walker thread will then exit if still running; join after:
            // To avoid deadlock when we broke early due to max_results, we drop rx explicitly via a trick:
            // (rx is still alive here; explicitly drop by name would require moving it; we attempt:)
            // The following drop is possible because rx is not used after.
            // However Rust will complain if we already used it in loop by reference – we can drop now.
            // (We do it after join attempt is not needed)
            // Note: handle.join() will wait for walker to notice sender error.
            // First drop receiver:
            // – this line is replaced by the compiler's drop at end; to force early, we use std::mem::drop via a scope:
            // We can't easily because rx is borrowed in loop... but loop finished.
            let _ = handle; // walker thread will finish when rx dropped at return
            // Force drop of rx by consuming it into a drop:
            // (This requires rx to be a variable; it is)
            // The join will happen in background? We need to wait by joining after rx drop.
            // Rust: we can do:
            // drop(rx); let _ = handle.join();
            // This is valid here.
            drop(rx);
            // handle was moved above with `let _ = handle;` – so this code path can't join. This is a known
            // minor inefficiency (thread detached) – process exit will terminate it.
            if write_error { 1 } else { 0 }
        }
    }
}

fn global_fd_ignore_path() -> Option<PathBuf> {
    // XDG_CONFIG_HOME (absolute) else HOME/.config
    if let Some(xdg) = std::env::var_os("XDG_CONFIG_HOME") {
        if !xdg.is_empty() {
            let p = PathBuf::from(&xdg);
            if p.is_absolute() {
                return Some(p.join("fd").join("ignore"));
            }
        }
    }
    if let Some(home) = std::env::var_os("HOME") {
        if !home.is_empty() {
            return Some(PathBuf::from(home).join(".config").join("fd").join("ignore"));
        }
    }
    None
}

fn get_exec_templates(matches: &clap::ArgMatches, id: &str) -> Vec<ExecTemplate> {
    let mut out = Vec::new();
    if let Some(groups) = matches.get_raw_occurrences(id) {
        for group in groups {
            let args: Vec<Vec<u8>> = group.map(|s: &OsStr| s.as_bytes().to_vec()).collect();
            if !args.is_empty() {
                out.push(ExecTemplate { args });
            }
        }
    }
    out
}

use std::ffi::OsStr;
use std::os::unix::ffi::OsStrExt;
RS
