//! Minimal terminal-size query used by the command-line parser.
//!
//! This implementation asks the operating system for the number of
//! columns and rows associated with the standard streams.

/// Terminal width in columns.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct Width(pub u16);

/// Terminal height in rows.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct Height(pub u16);

/// Returns the size of the terminal, probing stdout, stderr and stdin.
pub fn terminal_size() -> Option<(Width, Height)> {
    for fd in [libc::STDOUT_FILENO, libc::STDERR_FILENO, libc::STDIN_FILENO] {
        if let Some(size) = terminal_size_of(fd) {
