            (None,None)
        }
        _ => (None, None),
    }
}

pub fn compute_depth_for_path(path: &Path, roots: &[PathBuf]) -> usize {
    for root in roots {
        if let Ok(rel) = path.strip_prefix(root) {
            return rel.components().count();
        }
    }
    // fallback: number of normal components, minus leading curdir handling
    // For "./a/b", components include CurDir + 2 normals -> depth 2
    let mut n=0usize;
    for c in path.components() {
        if let std::path::Component::Normal(_) = c { n+=1; }
    }
    n
}

pub fn passes_for_path(path: &Path, depth: usize, file_name: &std::ffi::OsStr, ft_opt: Option<fs::FileType>, cfg: &Config, regexes: &[Regex]) -> bool {
    if depth < cfg.min_depth { return false; }
    if let Some(max) = cfg.max_depth_opt { if depth > max { return false; } }
    if !regexes.is_empty() {
        let subject_bytes: Vec<u8> = if cfg.full_path {
            let candidate = if cfg.absolute { absolutize_path(path) } else { path.to_path_buf() };
            absolute_for_match(&candidate, &cfg.cwd, cfg).into_bytes()
        } else {
            file_name.as_bytes().to_vec()
        };
        for re in regexes { if !re.is_match(&subject_bytes) { return false; } }
    }
    if let Some(tf) = &cfg.types {
        if let Some(ft) = ft_opt { if !tf.matches(path, &ft) { return false; } } else { return false; }
    }
    if let Some(exts) = &cfg.extensions {
        if !extension_matches(file_name, exts) { return false; }
    }
    if !cfg.sizes.is_empty() {
        let eff = match fs::metadata(path) { Ok(m)=>m, Err(_)=>return false };
        if !eff.is_file() { return false; }
        let link_md = match fs::symlink_metadata(path) { Ok(m)=>m, Err(_)=>return false };
        let sz = link_md.len();
        for sc in &cfg.sizes { if !sc.matches(sz) { return false; } }
    }
    if cfg.changed_within.is_some() || cfg.changed_before.is_some() {
        let md = match fs::symlink_metadata(path) { Ok(m)=>m, Err(_)=>return false };
        if !metadata_time_matches(&md, cfg.changed_within, cfg.changed_before) { return false; }
    }
    if let Some(owner) = &cfg.owner {
        if !owner.is_empty() {
            let md = match fs::symlink_metadata(path) { Ok(m)=>m, Err(_)=>return false };
            if !owner.matches(&md) { return false; }
        }
    }
    true
}

