            let mut has_ph = false;
            for a in &tpl.args {
                let (_, found) = text::replace_placeholders(a, dummy, cfg.path_separator.as_str());
                if found { has_ph = true; } else { est += a.len() + 1 + 8; }
            }
            if !has_ph { /* implicit placeholder added per result, accounted incrementally */ }
            est
        }).collect();
        // per-template per-result incremental estimate
        let increment = |tpl: &ExecTemplate, r: &SearchResult| -> usize {
            let dummy = Path::new("dummy");
