                    has_ph = true;
                    let (rep, _) = text::replace_placeholders(a, &r.display_path, cfg.path_separator.as_str());
                    inc += rep.len() + 1 + 8;
                }
            }
            if !has_ph {
                let (rep, _) = text::replace_placeholders(b"{}", &r.display_path, cfg.path_separator.as_str());
                inc += rep.len() + 1 + 8;
            }
            inc
        };
        let mut start = 0usize;
        while start < results.len() {
            let mut totals = base_ests.clone();
            let mut end = start;
            while end < results.len() {
                if batch_size > 0 && end - start >= batch_size { break; }
                let mut would_exceed = false;
                let mut new_totals = totals.clone();
                for (i, tpl) in templates.iter().enumerate() {
                    new_totals[i] += increment(tpl, &results[end]);
                    if new_totals[i] > limit { would_exceed = true; }
                }
                if would_exceed && end > start { break; }
                totals = new_totals;
                end += 1;
            }
            if end == start { end += 1; }
            chunks.push(&results[start..end]);
            start = end;
        }
    }
